    public func txSerializer(for schema: BindingSchema) -> @Sendable (Any) -> [UInt8] {
        switch schema {
        case .bool: return { var b = ByteBufferAllocator().buffer(capacity: 1); encodeBool($0 as! Bool, into: &b); return b.readBytes(length: b.readableBytes) ?? [] }
